# -*- coding: utf-8 -*-
"""Dex Hub lightweight runtime translation helper.

Kodi language folders are included for standard metadata/XML strings. This
module remains the runtime translator for the many dynamically-built labels,
notifications and dialog strings inside the addon.
"""
import xbmcaddon

ADDON = xbmcaddon.Addon()
_lang_cache = None


def _read_language_setting():
    """Read ui_language fresh from addon settings (no cache)."""
    try:
        # Re-instantiate Addon() so we get the freshest setting value.
        # Caching xbmcaddon.Addon() across invocations under
        # reuselanguageinvoker can hand back stale values when the user
        # changes settings mid-session.
        import xbmcaddon
        raw = (xbmcaddon.Addon().getSetting('ui_language') or 'English').strip().lower()
    except Exception:
        raw = 'english'
    compact = raw.replace('_', ' ').replace('-', ' ').strip()
    if compact in ('en', 'english') or compact.startswith('en'):
        return 'en'
    return 'ar'


def reset_language_cache():
    """Force re-read of the ui_language setting on the next current_language() call.

    Call this from a settings-changed hook so language flips apply without restart.
    v5.10.26: the translation memo is only dropped when the language actually
    changed; clearing it on every invocation re-ran the substring scan for
    every composed string on every folder render.
    """
    global _lang_cache
    previous = _lang_cache
    _lang_cache = None
    try:
        current = _read_language_setting()
    except Exception:
        current = None
    if previous is None or current != previous:
        _TR_MEMO.clear()
    _lang_cache = current


def current_language():
    global _lang_cache
    if _lang_cache is not None:
        return _lang_cache
    _lang_cache = _read_language_setting()
    return _lang_cache


def is_english():
    return current_language() == 'en'


